import type { Challenge } from './types'

/*
 * Reference pictures: PNG screenshots of each challenge's solution, one per checked viewport,
 * generated by `npm run references` into public/references/. A manifest records a content hash
 * per picture; a unit test compares it with the current challenge so a changed solution with an
 * outdated picture fails CI instead of confusing learners.
 */

export const REFERENCE_HEIGHT = 600

/** cyrb53: a small, fast, well-distributed string hash. Pure, so tests and the capture script agree. */
export function hashString(input: string, seed = 0): string {
  let h1 = 0xdeadbeef ^ seed
  let h2 = 0x41c6ce57 ^ seed
  for (let i = 0; i < input.length; i++) {
    const ch = input.charCodeAt(i)
    h1 = Math.imul(h1 ^ ch, 2654435761)
    h2 = Math.imul(h2 ^ ch, 1597334677)
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909)
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909)
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(36)
}

/** Everything that changes how the reference looks: the tree, the solution and the width. */
export function referenceKey(challenge: Pick<Challenge, 'items' | 'solution'>, width: number): string {
  return hashString(`${JSON.stringify(challenge.items)}\u0000${challenge.solution}\u0000${width}`)
}

export const referenceFile = (id: string, width: number) => `${id}-${width}.png`

export type ReferenceManifest = Record<string, Record<string, string>>
